#include <atomic>
#include <chrono>
#include <condition_variable>
#include <mutex>
#include <thread>

class Server {
public:
  std::atomic<bool> ready{false};
  std::condition_variable cv;
  std::mutex mtx;
  // a background worker sets ready once initialization completes and notifies cv
};

void wait_ready(Server& s) {
  std::unique_lock<std::mutex> lock(s.mtx);
  s.cv.wait(lock, [&s] { return s.ready.load(); });
}
```

